var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original library should correctly parse '1y' as 365.25 days
    // The patched version has a bug: y = d / 365.25, which is wrong
    const expectedOriginal = 1000 * 60 * 60 * 24 * 365.25; // 1 year in ms
    const actualOriginal = ms('1y');

    // Verify original behavior is correct
    assert.strictEqual(actualOriginal, expectedOriginal, 'Original ms should parse 1y as 365.25 days');

    // Now check the patched version: it should NOT give the same result
    // The bug makes it return 1 day / 365.25, which is ~2.7ms
    const expectedPatched = 1000 * 60 * 60 * 24 / 365.25; // 1 day divided by 365.25
    const actualPatched = ms('1y');

    // The patched version must NOT return the correct year value
    assert.notEqual(actualPatched, expectedOriginal, 'Patched version must not parse 1y as 365.25 days');

    // And it must return the wrong value (the one from the bug)
    assert.strictEqual(actualPatched, expectedPatched, 'Patched version should parse 1y as 1 day / 365.25');
  });
});

